        "общей строки «начало — окончание». Пятидневная рабочая неделя "
        "с фиксированным началом в 09:00 описывается семью записями "
        "графика, пять из которых рабочие, две — выходные. Сменный "
        "график «сутки через трое» характерен для охраны, диспетчерских "
