        "продолжительностью 12 или 24 часа с переходом через полночь. "
        "Гибкий график с плавающим началом — типичен для офисных "
        "сотрудников, для которых организация фиксирует обязательный "
        "интервал присутствия и допустимый коридор начала рабочего дня. "
        "Скользящий график со сдвигом начала на один час каждую "
        "неделю — встречается в торговых организациях. Все эти "
        "сценарии должны единообразно поддерживаться "
