            ["Г7", "Уход 18:01:00 при окончании 18:00", "overtime=1", "Пройден"],
            ["Г8", "Уход 17:59:00 при окончании 18:00", "early_leave=1", "Пройден"],
            ["Г9", "Ночная смена 20:00—08:00, уход 08:30", "overtime=30", "Пройден"],
